const ahora = new Date();
const filas = $input.all().map(i => i.json).filter(r => r.ID);

const vencidos = filas.filter(r => {
  if (r.NOTIFICADO === 'SI' || r.ESTADO === 'ENVIADO' || r.ESTADO === 'enviado') return false;
  if (!r.FECHA_LIMIT || !r.HORA) return false;
  const fechaValida = /^\d{4}-\d{2}-\d{2}$/.test(r.FECHA_LIMIT);
  const horaValida = /^([01]\d|2[0-3]):([0-5]\d)$/.test(r.HORA);
  if (!fechaValida || !horaValida) return false;
  const fechaHora = new Date(`${r.FECHA_LIMIT}T${r.HORA}:00`);
  return fechaHora <= ahora;
});

return vencidos
  .filter(r => r.CHAT_ID)
  .map(r => ({ json: {
    ID: r.ID,
    chatId: r.CHAT_ID,
    mensaje: r.DESCRIPCION,
    fecha: r.FECHA_LIMIT,
    hora: r.HORA
  }}));

const chatId = $('Router (lógica principal)').item.json.chatId;

// ── Datos acumulados desde la cadena Leer -> Recolectar (sin Merge) ────────
const prev = $('Recolectar LOGS Productividad').item.json;
const citas = Array.isArray(prev.citas) ? prev.citas : [];
const tareas = Array.isArray(prev.tareas) ? prev.tareas : [];
const logs = Array.isArray(prev.logs) ? prev.logs : [];
const usuarios = $input.all().map(i => i.json).filter(r => r && r.telegram_user);

// ── VALIDACIÓN: hojas sin datos suficientes ─────────────────────────────────
const hojasVacias = [];
if (citas.length === 0) hojasVacias.push('CITAS');
if (tareas.length === 0) hojasVacias.push('TAREAS');
if (logs.length === 0) hojasVacias.push('LOGS');
if (usuarios.length === 0) hojasVacias.push('USUARIOS');

if (usuarios.length === 0) {
  return [{ json: { chatId, respuesta:
    `📊 Reporte de productividad (AgendaBot)\n\n⚠️ No existen datos suficientes: la hoja USUARIOS está vacía o no tiene registros con telegram_user.\n\n1. Volver al menú Reportes\n2. Volver al menú principal` } }];
}
if (citas.length === 0 && tareas.length === 0 && logs.length === 0) {
  return [{ json: { chatId, respuesta:
    `📊 Reporte de productividad (AgendaBot)\n\n⚠️ No existen datos suficientes: las hojas CITAS, TAREAS y LOGS están vacías.\n\n1. Volver al menú Reportes\n2. Volver al menú principal` } }];
}

// ── Agrupar por telegram_user (nunca por nombre ni ID interno) ─────────────
// Se ignoran únicamente registros corruptos (sin telegram_user/creado_por), sin detener el workflow.
const porUsuario = {};
usuarios.forEach(u => {
  const id = u.telegram_user ? String(u.telegram_user).trim() : '';
  if (!id) return;
  porUsuario[id] = {
    telegram_user: id,
    nombre: u.nombre || '',
    total_citas: 0, citas_completadas: 0, citas_canceladas: 0,
    total_tareas: 0, tareas_completadas: 0, tareas_pendientes: 0,
    total_interacciones: 0
  };
});

citas.forEach(c => {
  const id = c.creado_por ? String(c.creado_por).trim() : '';
  if (!id || !porUsuario[id]) return; // registro corrupto o usuario no registrado -> se ignora
  porUsuario[id].total_citas++;
  if (c.estado === 'completada') porUsuario[id].citas_completadas++;
  if (c.estado === 'cancelada') porUsuario[id].citas_canceladas++;
});

tareas.forEach(t => {
  const id = t.creado_por ? String(t.creado_por).trim() : '';
  if (!id || !porUsuario[id]) return;
  porUsuario[id].total_tareas++;
  if (t.estado === 'completada') porUsuario[id].tareas_completadas++;
  if (t.estado === 'pendiente' || t.estado === 'en_progreso') porUsuario[id].tareas_pendientes++;
});

logs.forEach(l => {
  const id = l.telegram_user ? String(l.telegram_user).trim() : '';
  if (!id || !porUsuario[id]) return;
  porUsuario[id].total_interacciones++;
});

// ── Orden alfabético por telegram_user; ningún usuario registrado se omite ─
const listaUsuarios = Object.values(porUsuario).sort((a, b) => a.telegram_user.localeCompare(b.telegram_user));

// ── Resumen general ──────────────────────────────────────────────────────
const total_citas_registradas = citas.length;
const total_tareas_registradas = tareas.length;
const total_interacciones_bot = logs.length;

let usuario_mas_activo = 'N/D';
let maxInteracciones = -1;
listaUsuarios.forEach(u => {
  if (u.total_interacciones > maxInteracciones) {
    maxInteracciones = u.total_interacciones;
    usuario_mas_activo = u.nombre ? u.nombre : u.telegram_user;
  }
});

// ── Construcción del mensaje (formato exacto solicitado) ───────────────────
const LINEA = '━━━━━━━━━━━━━━';
let txt = `📊 Reporte de productividad (AgendaBot)\n`;
txt += `Resumen general\n`;
txt += `• Usuario más activo: ${usuario_mas_activo}\n`;
txt += `• Total citas registradas: ${total_citas_registradas}\n`;
txt += `• Total tareas registradas: ${total_tareas_registradas}\n`;
txt += `• Total interacciones: ${total_interacciones_bot}\n`;
txt += `${LINEA}\n`;
txt += `Detalle por usuario\n`;

listaUsuarios.forEach(u => {
  const etiqueta = u.nombre ? `@${u.nombre}` : `@${u.telegram_user}`;
  txt += `\n${etiqueta}\n`;
  txt += `• Citas: ${u.total_citas}\n`;
  txt += `• Completadas: ${u.citas_completadas}\n`;
  txt += `• Canceladas: ${u.citas_canceladas}\n`;
  txt += `• Tareas: ${u.total_tareas}\n`;
  txt += `• Hechas: ${u.tareas_completadas}\n`;
  txt += `• Pendientes: ${u.tareas_pendientes}\n`;
  txt += `• Interacciones: ${u.total_interacciones}\n`;
  txt += `${LINEA}\n`;
});

txt += `\n¿Qué deseas hacer ahora?\n1. Volver al menú Reportes\n2. Volver al menú principal`;

return [{ json: { chatId, respuesta: txt } }];
